flow.set("invinfo3p_rpc_response_topic", msg.rpcResponseTopic);
flow.set("invinfo3p_part1", null);
flow.set("invinfo3p_part2", null);
flow.set("invinfo3p_part3", null);

return msg;

msg.readGroup = "part1";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 100,
    quantity: 8
};
return msg;

// Store part1 data
let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}
if (Array.isArray(data)) {
    flow.set("invinfo3p_part1", data);
}

// Prepare part2 read
msg.readGroup = "part2";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 108,
    quantity: 7
};
return msg;

// Store part2 data
let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}
if (Array.isArray(data)) {
    flow.set("invinfo3p_part2", data);
}

// Prepare part3 read
msg.readGroup = "part3";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 115,
    quantity: 7
};
return msg;

// Store part3 data
let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}
if (Array.isArray(data)) {
    flow.set("invinfo3p_part3", data);
}

// Get all parts
const part1 = flow.get("invinfo3p_part1");
const part2 = flow.get("invinfo3p_part2");
const part3 = flow.get("invinfo3p_part3");

if (!part1 || !part2 || !part3) {
    node.error("Missing parts");
    return null;
}

// Combine: [100-107] + [108-114] + [115-121]
msg.combinedData = [...part1, ...part2, ...part3];
return msg;

const data = msg.combinedData;

if (!Array.isArray(data) || data.length < 22) {
    node.error("Invalid combined data: " + data.length + " registers");
    return null;
}

// Clear flow context
flow.set("invinfo3p_part1", null);
flow.set("invinfo3p_part2", null);
flow.set("invinfo3p_part3", null);

// Helper: Parse ASCII from packed register (2 chars per register)
function parseAsciiChar(val, high) {
    const byte = high ? ((val >> 8) & 0xFF) : (val & 0xFF);
    if (byte >= 0x20 && byte <= 0x7E) {
        return String.fromCharCode(byte);
    }
    return '';
}

// Helper: Parse Serial Number from registers 103-107 (10 ASCII chars)
function parseSerialNumber(regs) {
    let sn = '';
    for (let i = 0; i < 5; i++) {
        sn += parseAsciiChar(regs[i], true);  // High byte first
        sn += parseAsciiChar(regs[i], false); // Low byte second
    }
    return sn.trim();
}

// Helper: Parse device type (100)
function parseDeviceType(val) {
    switch(val) {
        case 0x03: return "Single-phase LV Hybrid";
        case 0x05: return "Three-phase LV Hybrid";
        case 0x06: return "Three-phase HV Hybrid";
        default: return "Unknown (0x" + val.toString(16) + ")";
    }
}

// Helper: Parse rated power from two registers (0.1W scale)
function parseRatedPower(low, high) {
    const combined = (high << 16) | low;
    return combined * 0.1; // Returns in Watts
}

// Parse registers (index mapping after combining parts)
// Part 1: [0-7]   = 100-107
// Part 2: [8-14]  = 108-114  
// Part 3: [15-21] = 115-121

const deviceType = parseDeviceType(data[0]);           // 100
const serialNumber = parseSerialNumber(data.slice(3, 8)); // 103-107
const controlHardware = data[14];                       // 114 (part2 index 6)
const controlMasterVersion = data[15];                  // 115 (part3 index 0)
const commField1 = data[16];                            // 116
const commField2 = data[17];                            // 117
const commMasterVersion = data[18];                     // 118
const ratedPowerW = parseRatedPower(data[20], data[21]); // 120-121

// Derive MPPT count and phase count from deviceType
let mpptCount = 4;
let phaseCount = 3;
if (data[0] === 0x03) {
    mpptCount = 3;
    phaseCount = 1;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";

const state = {
    kind: "InverterInfoState",
    timestampUtc: new Date().toISOString(),
    version: 1,

    deviceType: deviceType,
    deviceTypeCode: data[0],
    modbusAddress: 1,
    protocolVersion: null,
    serialNumber: serialNumber,

    ratedPowerW: ratedPowerW,
    ratedPowerKw: Math.round(ratedPowerW / 100) / 10,

    mpptCount: mpptCount,
    phaseCount: phaseCount,

    gridVoltageRating: null,
    safetyType: null,

    firmware: {
        controlBoard: null,
        controlBoardAux: null,
        controlHardware: controlHardware,
        controlMasterVersion: controlMasterVersion,
        communicationBoard: null,
        commBoardField1: commField1,
        commBoardField2: commField2,
        commMasterVersion: commMasterVersion,
        chipType: null,
        ratedPowerClass: null
    },

    rawRegisters: data
};

const rpcResponseTopic = flow.get("invinfo3p_rpc_response_topic");
flow.set("invinfo3p_rpc_response_topic", null);

msg.payload = state;
msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;
